import type {
  ExtensionAPI,
  ToolLoadout,
  ToolLoadoutChanges,
} from "@earendil-works/pi-coding-agent";

import { createPiToolCatalog, type PiToolCatalog, piToolPrompt } from "./pi-tools.js";

const PIT_TOOL_NAME = "typescript";

/** Tool selection resolved at session start from the user's and a trusted project's `pit.json`. */
export interface PitToolSelection {
  /** Tools declared to the model alongside `typescript` (`allowedTools`). */
  allowedTools: RegExp[];
}

export function createPitToolSelection(): PitToolSelection {
  return { allowedTools: [] };
}

/** Whole-name, case-sensitive patterns in which `*` matches any sequence. */
export function compileToolPatterns(patterns: readonly string[]): RegExp[] {
  return patterns.map(
    (pattern) =>
      new RegExp(`^${pattern.replace(/[.+?^${}()|[\]\\]/g, "\\$&").replace(/\*/g, ".*")}$`),
  );
}

function isAllowed(selection: PitToolSelection, name: string): boolean {
  return selection.allowedTools.some((pattern) => pattern.test(name));
}

/**
 * Adds `typescript` and the registered `allowedTools` matches to the active tools. Tools other
 * extensions activated stay active, so MCP tools and orchestrators such as `codemode` remain
 * callable; {@link pitLoadout} hides their declarations instead.
 */
export function activatePitTools(pi: ExtensionAPI, selection: PitToolSelection): void {
  const exceptions = selection.allowedTools.length
    ? pi
        .getAllTools()
        .map(({ name }) => name)
        .filter((name) => isAllowed(selection, name))
    : [];
  pi.setActiveTools([...new Set([PIT_TOOL_NAME, ...pi.getActiveTools(), ...exceptions])]);
}

/**
 * Hides the declarations of tools the model would otherwise see beside `typescript`. They stay
 * active and callable. Declared: `typescript`, `allowedTools` matches, MCP tools configured with
 * `direct` exposure, and tools that are declared only because a tool such as `tool_search`
 * loaded them (`codemode` or `deferred` exposure). `typescript`'s description lists the callable
 * tools a program can inject from `tools`; Pi passes the original description every time.
 */
export function pitLoadout(
  loadout: ToolLoadout,
  selection: PitToolSelection,
  catalog: PiToolCatalog = createPiToolCatalog(loadout.callable, (name) =>
    loadout.getPromptGuidelines(name),
  ),
): ToolLoadoutChanges {
  const own = loadout.declared.find(({ name }) => name === PIT_TOOL_NAME);
  const prompt = piToolPrompt(catalog);
  return {
    ...(own && prompt ? { descriptions: { [PIT_TOOL_NAME]: own.description + prompt } } : {}),
    hiddenDeclarations: loadout.declared
      .map(({ name }) => name)
      .filter(
        (name) =>
          name !== PIT_TOOL_NAME && !isAllowed(selection, name) && hiddenByDefault(loadout, name),
      ),
  };
}

function hiddenByDefault(loadout: ToolLoadout, name: string): boolean {
  switch (loadout.getExposure(name)) {
    case "model-only":
      return true;
    case "direct":
      // MCP's default exposure is `codemode`, so a `direct` MCP tool is an explicit user choice.
      return !loadout.getNamespace(name)?.name.startsWith("mcp__");
    default:
      return false;
  }
}
import type { ToolExecutionApi, ToolRegistration } from "@earendil-works/pi-durable";

import {
  createPiToolCatalog,
  describePiTool,
  type PiToolCatalog,
  searchPiTools,
  TOOL_INDEX_NAMESPACE,
} from "../functions/pi-tools.js";
import type { HostToolCall } from "../host/native-dispatcher.js";
import { stringValue as string } from "../shared/argument-values.js";
import { isRecord } from "../shared/records.js";
import type { ImageBlock, ImageCollector } from "../workspace/view-image.js";

type ToolContext = Parameters<ToolRegistration["execute"]>[2];

/**
 * Tools Pit does not bind on pi-durable: itself and other orchestrators. Unlike on Pi, the file and
 * shell tools stay: the host chose them, and they act in its environment rather than Pit's process.
 */
const ORCHESTRATORS = new Set(["typescript", "codemode", "tool_search"]);

/** The host tools a call may run through `tools.*`: the agent's tools other callers may use. */
export function createDurableToolCatalog(callable: readonly ToolRegistration[]): PiToolCatalog {
  return createPiToolCatalog(
    callable.map((tool) => ({
      name: tool.name,
      description: tool.description,
      parameters: tool.parameters,
      ...(tool.structuredOutputSchema === undefined
        ? {}
        : { outputSchema: tool.structuredOutputSchema }),
    })),
    undefined,
    ORCHESTRATORS,
  );
}

const MAX_LISTED_TOOLS = 40;

/** Tells the model which host tools `tools.*` reaches, as Pi's tool description does. */
export function durableToolsPrompt(catalog: PiToolCatalog): string | undefined {
  const names = [...catalog.bindings.keys()];
  if (names.length === 0) return undefined;
  const listed = names.slice(0, MAX_LISTED_TOOLS).join(", ");
  const more =
    names.length > MAX_LISTED_TOOLS
      ? `, … ${names.length - MAX_LISTED_TOOLS} more (find them with toolIndex.search)`
      : "";
  return [
    `The host's other tools are injectable from \`tools\`: ${listed}${more}.`,
    "Before calling one, inject `toolIndex: { search, describe }`: describe(name) returns its declaration. Then call it, for example `async ({ tools: { NAME } }) => NAME({ ... })`.",
    "Calls run through the host like direct tool calls, in the host's environment. A call returns the tool's declared structured value, otherwise its text. A failed call throws.",
  ].join("\n");
}

function textOf(value: unknown): string {
  if (typeof value === "string") return value;
  const blocks = Array.isArray(value) ? value : [value];
  return blocks
    .flatMap((block) =>
      isRecord(block) && block.type === "text" && typeof block.text === "string"
        ? [block.text]
        : [],
    )
    .join("\n");
}

function imagesOf(value: unknown): ImageBlock[] {
  const blocks = Array.isArray(value) ? value : [value];
  return blocks.flatMap((block) =>
    isRecord(block) &&
    block.type === "image" &&
    typeof block.data === "string" &&
    typeof block.mimeType === "string"
      ? [{ type: "image" as const, data: block.data, mimeType: block.mimeType }]
      : [],
  );
}

export interface DurableToolCallServices {
  api: Pick<ToolExecutionApi, "executeTool">;
  context: ToolContext;
  catalog: PiToolCatalog;
  images: ImageCollector;
}

/**
 * Runs one `tools.*` or `toolIndex.*` call. Tool calls go through `executeTool()`, so the host's
 * argument validation and tool hooks apply as for model calls, and the Harness validates a
 * declared structured output.
 */
export async function callDurableTool(
  services: DurableToolCallServices,
  { namespace, method, args }: HostToolCall,
): Promise<unknown> {
  const { catalog } = services;
  if (namespace === TOOL_INDEX_NAMESPACE) {
    if (method === "search") {
      const limit = typeof args[1] === "number" ? args[1] : undefined;
      return searchPiTools(catalog, string(args[0], "query"), limit);
    }
    return describePiTool(catalog, string(args[0], "name"));
  }
  const entry = catalog.bindings.get(method);
  /* v8 ignore next -- validation binds only the catalog's tools. */
  if (!entry) throw new Error(`Unknown host function: ${namespace}.${method}`);
  if (args.length > 1) {
    throw new Error(`${namespace}.${method} expects 0-1 argument(s); received ${args.length}`);
  }
  const input = args[0] ?? {};
  if (!isRecord(input)) throw new Error(`${namespace}.${method} expects an arguments object`);
  const result = await services.api.executeTool(
    entry.toolName,
    input as Parameters<ToolExecutionApi["executeTool"]>[1],
    services.context,
  );
  if (result.isError) {
    const text =
      textOf(result.structuredOutput) ||
      result.diagnostics
        .filter((diagnostic) => diagnostic.severity === "error")
        .map((diagnostic) => diagnostic.message)
        .join("; ");
    throw new Error(text ? `${entry.toolName} failed: ${text}` : `${entry.toolName} failed`);
  }
  if (entry.outputSchema) {
    /* v8 ignore next 3 -- the Harness rejects a declared schema's missing structured output. */
    if (result.structuredOutput === undefined) {
      throw new Error(`${entry.toolName} returned no structured result despite declaring one`);
    }
    return result.structuredOutput;
  }
  for (const image of imagesOf(result.structuredOutput)) {
    services.images.attachBlock(image, entry.toolName);
  }
  return textOf(result.structuredOutput);
}
import { readFile } from "node:fs/promises";
import { join } from "node:path";

import type { ExtensionContext } from "@earendil-works/pi-coding-agent";

import { hostPlatform } from "../../shared/host-platform.js";
import { isRecord } from "../../shared/records.js";
import { type FunctionRegistry, validateSavedFunctionSource } from "../core.js";
import { functionRelativePath } from "../identifier.js";
import {
  getPersistentFunctionMetadata,
  type PersistentFunctionMetadataRegistry,
} from "../source.js";
import {
  isMissingFileError,
  assertPersistentPath,
  readPersistentFunctionCandidates,
  removePersistentFunctionFile,
  writePersistentFunctionFile,
} from "./files.js";
import { type ConfiguredFunctionPaths, defaultProjectFunctionDirectory } from "./paths.js";
import { validatePersistentFunction, filterPersistentIdentifiers } from "./validation.js";

/**
 * Settings from Pi's user `pit.json` and a trusted project's `.pi/pit.json`. A project's
 * allowedTools replaces the user's; an invalid or unreadable project file grants no exceptions.
 * `paths` comes only from the project file.
 */
interface PitProjectConfig {
  allowedTools?: string[];
  /** Directories for project and user functions, as written; see resolveFunctionPaths. */
  paths?: ConfiguredFunctionPaths;
  error?: string;
}

function projectFunctionPath(directory: string, name: string): string {
  return join(directory, functionRelativePath(name));
}

function configuredPaths(value: unknown): ConfiguredFunctionPaths | undefined {
  if (value === undefined) return undefined;
  if (!isRecord(value)) throw new Error("paths must be an object");
  const paths: ConfiguredFunctionPaths = {};
  for (const key of ["project", "user"] as const) {
    const path = value[key];
    if (path === undefined) continue;
    if (typeof path !== "string" || path.trim().length === 0) {
      throw new Error(`paths.${key} must be a non-empty string`);
    }
    paths[key] = path;
  }
  return paths;
}

/**
 * Reads one `pit.json`. A missing file yields no settings; an unreadable or invalid file yields only
 * an error. User files support only allowedTools: their `paths` is ignored with a warning, without
 * discarding their allowedTools.
 */
async function readPitConfig(file: string, scope: "user" | "project"): Promise<PitProjectConfig> {
  let source: string;
  try {
    source = await readFile(file, "utf8");
  } catch (error) {
    if (isMissingFileError(error)) {
      return {};
    }
    // readFile rejects with a Node system error, whose message repeats the path: give its code.
    return { error: `Cannot read ${file}: ${(error as { code?: string }).code}` };
  }
  try {
    const config = JSON.parse(source) as unknown;
    if (!isRecord(config)) {
      throw new Error("configuration must be a JSON object");
    }
    const allowedTools = config.allowedTools;
    if (
      allowedTools !== undefined &&
      (!Array.isArray(allowedTools) ||
        !allowedTools.every((name) => typeof name === "string" && name.trim().length > 0))
    ) {
      throw new Error("allowedTools must be an array of non-empty strings");
    }
    const selection = allowedTools === undefined ? {} : { allowedTools };
    if (scope === "user") {
      return config.paths === undefined
        ? selection
        : { ...selection, error: `Ignored paths in ${file}: function paths are project-only` };
    }
    const paths = configuredPaths(config.paths);
    return { ...selection, ...(paths === undefined ? {} : { paths }) };
  } catch (error) {
    return { error: `Invalid ${file}: ${(error as Error).message}` };
  }
}

/** The directory facts a project load needs; the Pi context provides them. */
export type ProjectLoadContext = Pick<ExtensionContext, "cwd" | "isProjectTrusted">;

export async function loadPitProjectConfig(
  ctx: ProjectLoadContext,
  agentDir = hostPlatform().agentDir(),
): Promise<PitProjectConfig> {
  const [user, project] = await Promise.all([
    readPitConfig(join(agentDir, "pit.json"), "user"),
    ctx.isProjectTrusted()
      ? readPitConfig(join(ctx.cwd, hostPlatform().configDirName, "pit.json"), "project")
      : Promise.resolve<PitProjectConfig>({}),
  ]);
  const allowedTools = project.error ? [] : (project.allowedTools ?? user.allowedTools);
  const error = [user.error, project.error].filter(Boolean).join("; ");
  return {
    ...project,
    ...(allowedTools === undefined ? {} : { allowedTools }),
    ...(error ? { error } : {}),
  };
}

export async function saveProjectFunction(
  directory: string,
  name: string,
  source: string,
  storage: FunctionRegistry | { registry: FunctionRegistry; user: ReadonlyMap<string, string> },
): Promise<boolean> {
  const registry = storage instanceof Map ? storage : storage.registry;
  const user = storage instanceof Map ? new Map<string, string>() : storage.user;
  validateSavedFunctionSource(source);
  const candidates = new Map(registry);
  candidates.set(name, source);
  validatePersistentFunction(name, source, candidates, { layer: "project", userFunctions: user });
  const replaced = registry.has(name);
  await assertPersistentPath(directory, name);
  await writePersistentFunctionFile(projectFunctionPath(directory, name), source);
  registry.set(name, source);
  return replaced;
}

export async function removeProjectFunction(directory: string, name: string): Promise<boolean> {
  await assertPersistentPath(directory, name);
  return removePersistentFunctionFile(projectFunctionPath(directory, name));
}

export async function loadProjectFunctions(
  ctx: ProjectLoadContext,
  registry: FunctionRegistry,
  metadata: PersistentFunctionMetadataRegistry,
  {
    user = new Map(),
    invalidDefinitions = new Map(),
    invalidUser = new Map(),
    directory = defaultProjectFunctionDirectory(ctx.cwd),
  }: {
    user?: ReadonlyMap<string, string>;
    invalidDefinitions?: Map<string, string>;
    invalidUser?: ReadonlyMap<string, string>;
    /** The resolved project-function directory; defaults to `.pi/functions`. */
    directory?: string;
  } = {},
): Promise<string[]> {
  registry.clear();
  metadata.clear();
  invalidDefinitions.clear();
  if (!ctx.isProjectTrusted()) {
    return [];
  }

  const { candidates, errors, invalid } = await readPersistentFunctionCandidates({
    directory,
    metadata: getPersistentFunctionMetadata,
  });

  for (const [id, error] of invalid) invalidDefinitions.set(id, error);

  const sources = new Map([...candidates].map(([id, value]) => [id, value.source]));
  filterPersistentIdentifiers(sources, {
    layer: "project",
    userFunctions: user,
    invalidDefinitions,
    errors,
  });
  for (const [name, value] of candidates) {
    if (!sources.has(name)) continue;
    try {
      validatePersistentFunction(name, value.source, sources, {
        layer: "project",
        userFunctions: user,
        invalidDefinitions: new Map([...invalidUser, ...invalidDefinitions]),
        checkAll: false,
      });
      registry.set(name, value.source);
      metadata.set(name, value.metadata);
    } catch (error) {
      errors.push(`${name}.ts: ${(error as Error).message}`);
      invalidDefinitions.set(name, (error as Error).message);
    }
  }
  return errors;
}
